package com.gameaggregator.clientservice.domain;import jakarta.persistence.*;import java.util.UUID;@Entity @Table(name="client_organizations") public class ClientOrganization{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID tenantId;@Column(nullable=false,unique=true)public String slug;@Column(nullable=false)public String name;protected ClientOrganization(){}public ClientOrganization(UUID t,String s,String n){tenantId=t;slug=s;name=n;}}
